FILES = [
    ('КХ_ДанныеОпера', '01_data_opera_commented.txt'),
    ('КХ_ДанныеПрайсЧекеры', '02_data_pc_commented.txt'),
    ('КХ_ДанныеСтруктурныхЕдиниц', '03_data_units_commented.txt'),
    ('КХ_ОбменШиныОпера', '04_exchange_opera_commented.txt'),
    ('КХ_ОбменШиныПрайсЧекеры', '05_exchange_pc_commented.txt'),
    ('КХ_ОбменСтруктурныхЕдиниц', '06_exchange_units_commented.txt'),
]

def without_full_comments(text):
    return ''.join(line for line in text.splitlines(True) if not line.lstrip().startswith('//'))

manifest = []
for module, download_name in FILES:
    path = ROOT / 'ОбщиеМодули' / (module + '.bsl')
    before = path.read_text(encoding='utf-8-sig')
    definitions = re.findall(r'^(?:Функция|Процедура) (\w+)\(', before, re.M)
    assert len(definitions) == len(set(definitions))
    assert set(definitions) == set(DOCS[module]), (module, set(definitions) ^ set(DOCS[module]))
    assert 'Пояснения к методам' not in before, 'Do not insert comments twice'
    backup = PATCH / 'ДоПравки' / path.name
    backup.parent.mkdir(parents=True, exist_ok=True)
    backup.write_text(before, encoding='utf-8')
    def comment_method(match):
        name = match.group(2)
        lines = ['// {{ semidockij - 27.10.2026 - Пояснения к методам']
        lines += ['// ' + line for line in DOCS[module][name]]
        lines += ['// }} semidockij - 27.10.2026']
        return '\n'.join(lines) + '\n' + match.group(0)
    after = re.sub(r'^(Функция|Процедура) (\w+)\(', comment_method, before, flags=re.M)
    assert without_full_comments(before) == without_full_comments(after)
    path.write_text(after, encoding='utf-8')
    txt = b'\xef\xbb\xbf' + after.replace('\n', '\r\n').encode('utf-8')
    (DOWNLOADS / download_name).write_bytes(txt)
    (ROOT / 'ДляКопирования' / (module + '.txt')).write_bytes(txt)
    (ROOT / 'ДляКопирования' / (module + '.md')).write_text(
        f'Полный общий модуль `{module}`. Редакция с пояснениями 27.10.2026. Скопируйте содержимое блока.\n\n```bsl\n'
        + after.rstrip('\n') + '\n```\n', encoding='utf-8')
    assert (DOWNLOADS / download_name).read_text(encoding='utf-8-sig') == after
    (PATCH / (module + '.diff')).write_text(''.join(difflib.unified_diff(
        before.splitlines(True), after.splitlines(True), fromfile='before', tofile='after')), encoding='utf-8')
    manifest.append({'module': module, 'methods_documented': len(definitions),
                     'code_unchanged_ignoring_full_comment_lines': True,
                     'sha256': hashlib.sha256(txt).hexdigest(), 'download': download_name})

(PATCH / 'Манифест.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'modules': len(manifest), 'methods': sum(x['methods_documented'] for x in manifest),
                  'checks': 'All method descriptions present; executable source unchanged; TXT round-trip identical'}, ensure_ascii=False))
